namespace CleanArchitecture.Blazor.Application.Features.Holidays.Specifications;
#nullable disable warnings
/// <summary>
/// Specification class for advanced filtering of Holidays.
/// </summary>
public class HolidayAdvancedSpecification : Specification<Holiday>
{
    public HolidayAdvancedSpecification(HolidayAdvancedFilter filter)
    {
        DateTime today = DateTime.UtcNow;
        var todayrange = today.GetDateRange(HolidayListView.TODAY.ToString(), filter.CurrentUser.LocalTimeOffset);
        var last30daysrange = today.GetDateRange(HolidayListView.LAST_30_DAYS.ToString(),filter.CurrentUser.LocalTimeOffset);

        Query.Where(q => q.Date != null)
             .Where(filter.Keyword,!string.IsNullOrEmpty(filter.Keyword))
             .Where(q => q.CreatedById == filter.CurrentUser.UserId, filter.ListView == HolidayListView.My && filter.CurrentUser is not null)
             .Where(x => x.CreatedAt >= todayrange.Start && x.CreatedAt < todayrange.End.AddDays(1), filter.ListView == HolidayListView.TODAY)
             .Where(x => x.CreatedAt >= last30daysrange.Start, filter.ListView == HolidayListView.LAST_30_DAYS);
       
    }
}
